import React, {useEffect, useState} from 'react';
import { MatrixInput } from './MatrixInput';
import { MatrixTextInput } from './MatrixTextInput';
import { FileUpload } from './FileUpload';
import { ResultsDisplay } from './ResultsDisplay';
import { IterationTable } from './IterationTable';
import { lab1Api } from '../../services/api';
import { SolutionResponse } from '../../types';
import toast from 'react-hot-toast';

type InputMode = 'manual' | 'text' | 'file';

export const SLAUPage: React.FC = () => {
    const [n, setN] = useState<number>(3);
    const [inputMode, setInputMode] = useState<InputMode>('manual');
    const [matrix, setMatrix] = useState<number[][]>(
        Array(3).fill(0).map(() => Array(3).fill(0))
    );
    const [vector, setVector] = useState<number[]>(Array(3).fill(0));
    const [epsilon, setEpsilon] = useState<number>(0.0001);
    const [maxIterations, setMaxIterations] = useState<number>(100);
    const [loading, setLoading] = useState<boolean>(false);
    const [result, setResult] = useState<SolutionResponse | null>(null);

    useEffect(() => {
        setMatrix(prevMatrix => {
            const newMatrix = Array(n).fill(0).map((_, i) => {
                return Array(n).fill(0).map((_, j) => {
                    return (prevMatrix[i] && prevMatrix[i][j] !== undefined)
                        ? prevMatrix[i][j]
                        : 0;
                });
            });
            return newMatrix;
        });

        setVector(prevVector => {
            return Array(n).fill(0).map((_, i) => {
                return (prevVector[i] !== undefined) ? prevVector[i] : 0;
            });
        });

        setResult(null);
    }, [n]);

    const updateData = (newMatrix: number[][], newVector: number[]) => {
        setMatrix(newMatrix);
        setVector(newVector);
        setN(newMatrix.length);
        setResult(null);
    };

    const handleSolve = async () => {
        setLoading(true);
        try {
            const response = await lab1Api.solve({
                matrix,
                vector,
                params: { epsilon, maxIterations }
            });
            setResult(response.data);
            if (response.data.status === 'success') {
                toast.success('Выполнено');
            } else {
                toast.error(response.data.message);
            }
        } catch (error: any) {
            toast.error('Ошибка соединения с сервером');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mx-auto px-4 py-8 max-w-5xl font-sans text-slate-800">
            {/* New Header - Modern & Minimalist */}
            <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4 border-b-4 border-slate-900 pb-6">
                <div className="flex items-center gap-4">
                    <div className="bg-slate-900 text-white p-2 text-2xl font-black rounded">Σ</div>
                    <div>
                        <h1 className="text-2xl font-black uppercase tracking-tighter leading-none">Computational Math</h1>
                        <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Lab #01 • Iterative Methods</p>
                    </div>
                </div>
                <div className="flex flex-col text-right">
                    <span className="text-sm font-bold border-b-2 border-slate-100 mb-1 pb-1">Ясаков А. А. | P3213</span>
                    <span className="text-[10px] text-slate-400 font-mono tracking-widest">SYSTEM_VERSION: 1.0.4-STABLE</span>
                </div>
            </header>

            {/* "Search Bar" Style Params Panel */}
            <div className="bg-slate-900 p-1 rounded-xl shadow-2xl mb-8 group transition-all hover:ring-4 hover:ring-slate-200">
                <div className="bg-white rounded-lg p-2 flex flex-wrap items-center gap-2">
                    <div className="flex-grow flex items-center bg-slate-50 px-4 py-2 rounded-md border-2 border-transparent focus-within:border-slate-200 transition-all">
                        <span className="text-slate-400 mr-3 text-lg">🔍</span>
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-slate-400 uppercase leading-none mb-1">Method Search/Target</span>
                            <span className="text-sm font-bold">Gauss-Seidel Solver (Variant 20)</span>
                        </div>
                    </div>

                    <div className="flex items-center gap-4 px-4 border-l border-slate-100">
                        <div className="flex flex-col">
                            <label className="text-[9px] font-black text-slate-400 uppercase mb-1">Dimension</label>
                            <input
                                type="number"
                                value={n}
                                onChange={(e) => setN(Math.min(Math.max(parseInt(e.target.value) || 1, 1), 20))}
                                className="w-12 text-sm font-bold bg-transparent focus:outline-none"
                            />
                        </div>
                        <div className="flex flex-col border-l border-slate-100 pl-4">
                            <label className="text-[9px] font-black text-slate-400 uppercase mb-1">Precision</label>
                            <input
                                type="number"
                                step="0.0001"
                                value={epsilon}
                                onChange={(e) => setEpsilon(parseFloat(e.target.value))}
                                className="w-20 text-sm font-bold bg-transparent focus:outline-none"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Input Section */}
            <div className="bg-white border-2 border-slate-100 rounded-2xl overflow-hidden shadow-sm mb-8">
                <div className="flex bg-slate-50 p-1 border-b-2 border-slate-100">
                    {(['manual', 'text', 'file'] as InputMode[]).map((mode) => (
                        <button
                            key={mode}
                            onClick={() => setInputMode(mode)}
                            className={`flex-1 py-3 text-[10px] font-black uppercase tracking-[0.2em] rounded-xl transition-all ${
                                inputMode === mode ? 'bg-white text-slate-900 shadow-sm ring-1 ring-slate-200' : 'text-slate-400 hover:text-slate-600'
                            }`}
                        >
                            {mode === 'manual' ? 'Grid Input' : mode === 'text' ? 'Raw Text' : 'Import File'}
                        </button>
                    ))}
                </div>

                <div className="p-8">
                    <div className="overflow-x-auto min-h-[200px]">
                        {inputMode === 'manual' && <MatrixInput n={n} matrix={matrix} vector={vector} onChange={updateData} />}
                        {inputMode === 'text' && <MatrixTextInput n={n} matrix={matrix} vector={vector} onChange={updateData} />}
                        {inputMode === 'file' && <FileUpload onDataLoaded={(data) => updateData(data.matrix, data.vector)} />}
                    </div>

                    <button
                        onClick={handleSolve}
                        disabled={loading}
                        className="mt-8 w-full py-4 bg-slate-900 hover:bg-black text-white font-black uppercase tracking-[0.3em] text-xs rounded-xl transition-all transform active:scale-[0.98] disabled:bg-slate-200"
                    >
                        {loading ? 'Processing...' : 'Run Analysis'}
                    </button>
                </div>
            </div>

            {/* Results Section */}
            <div className="space-y-6">
                {result ? (
                    <div className="pt-8 border-t-4 border-slate-900 animate-in slide-in-from-bottom-4 duration-700">
                        <div className="flex items-center gap-4 mb-8">
                            <h2 className="text-2xl font-black uppercase tracking-tighter">Analysis Report</h2>
                            <div className="h-[2px] flex-grow bg-slate-100"></div>
                        </div>

                        {result.status === 'error' ? (
                            <div className="p-6 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm font-bold rounded-r-xl">
                                System Error: {result.message}
                            </div>
                        ) : (
                            <div className="space-y-12">
                                <ResultsDisplay result={result} />
                                <div className="p-6 bg-slate-50 rounded-2xl border-2 border-slate-100">
                                    <h3 className="text-xs font-black uppercase text-slate-400 mb-6 tracking-widest">Iteration Matrix History</h3>
                                    <IterationTable history={result.iterationHistory} solution={result.solution} />
                                </div>
                            </div>
                        )}
                    </div>
                ) : (
                    <div className="py-20 text-center border-4 border-dashed border-slate-100 rounded-3xl">
                        <div className="text-4xl mb-4 opacity-20">📊</div>
                        <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.5em]">System Ready • Awaiting Input</p>
                    </div>
                )}
            </div>
        </div>
    );
};
